public async Task<IReadOnlyList<RelayTaskItem>> ListAsync(
    bool includeNeedsReview = true,
    CancellationToken cancellationToken = default)
{
    // Best-effort removal of the legacy .relay-scratch/ directory. Agents
    // used to write throwaway artifacts (screenshots, probes) there; that
    // path is retired and stale copies leak into target repos as untracked
    // files. Cleanup is attempted on every workspace open/refresh.
    TryDeleteLegacyScratch();

    var loaded = await RelayConfigLoader.TryLoadAsync(RootPath, cancellationToken);

private static bool IsSkippedName(string name) =>
    name.StartsWith("DONE-", StringComparison.OrdinalIgnoreCase) ||
    name.StartsWith("IGNORE-", StringComparison.OrdinalIgnoreCase);

private void TryDeleteLegacyScratch()
{
    var legacyScratch = Path.Combine(RootPath, ".relay-scratch");
    if (!Directory.Exists(legacyScratch))
        return;

    try { Directory.Delete(legacyScratch, recursive: true); }
    catch (IOException) { /* best-effort */ }
    catch (UnauthorizedAccessException) { /* best-effort */ }
}

